package io.ledgerflow.events;

import java.util.UUID;

/** How every service refers to a wallet. Agreed once, here. */
public record WalletRef(UUID accountId, String label) {}

package io.ledgerflow.events;

/**
 * Minor units only - 4500 means GBP 45.00.
 * Never use double for money: 0.1 + 0.2 is not 0.3 in binary floating point.
 */
public record Money(long minorUnits, String currency) {

    public Money {
        if (currency == null || currency.length() != 3)
            throw new IllegalArgumentException("currency must be an ISO-4217 code");
    }

    public static Money gbp(long minorUnits) { return new Money(minorUnits, "GBP"); }
}
